#pragma once
#include <cstdint>
#include <string_view>

// Large (32 px) glyphs for page titles, generated by scripts/prepare-title-font.py. The whole
// file is held in memory (about 70 KiB). Characters outside the file report no glyph.
struct TitleGlyph {
    uint8_t advance, width, height;
    const unsigned char* alpha;  // width*height 4-bit coverage values, two per byte, low nibble first
};
bool titleFontInit(const char* path);
void titleFontShutdown();
bool titleFontReady();
const TitleGlyph* titleGlyph(uint32_t codepoint);
// Width of `text` in pixels, or -1 when a character has no glyph.
int titleMeasure(std::string_view text);
